-- ============================================================
-- 0042 — Curadoria dos textos-base da RNC: Eletromecânica (ME)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- ME-01 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se faltar componente estrutural principal (perfil, torque tube, mancal ou módulo) ou houver dano de transporte que comprometa a integridade da montagem.',
  texto_fundamentacao_normativa = 'O recebimento e a conferência de materiais constituem requisito de controle de qualidade que antecede a liberação da etapa de montagem: o romaneio (packing list) deve ser confrontado, item a item, com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e com as especificações e listas de embarque do fabricante, registrando-se eventuais avarias de transporte. O critério "Romaneio × projeto; danos de transporte registrados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, assegurando a rastreabilidade de quantidades, referências e estado de conservação dos componentes antes de sua incorporação à estrutura.',
  texto_risco_consequencia = 'A ausência de conferência permite a incorporação de componentes trocados, incompletos ou avariados à montagem, gerando retrabalho, paralisações por falta de material, comprometimento estrutural do tracker e perda do prazo de reclamação de avarias junto à transportadora e ao fornecedor. Enquanto não sanada, a condição mantém indefinido o estoque efetivamente apto à instalação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer a conferência confrontando romaneio × projeto executivo aprovado e especificações do fabricante, quantificando faltas e sobras; (ii) segregar e identificar os itens avariados ou não conformes, abrindo o respectivo registro de avaria e a comunicação formal ao fornecedor/transportadora dentro do prazo contratual; (iii) evidenciar a conferência e o estado dos componentes com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o desalinhamento ou fora de prumo comprometer o acoplamento do torque tube entre módulos ou o curso livre de rastreamento das fileiras.',
  texto_fundamentacao_normativa = 'O alinhamento em planta e o prumo das fileiras devem permanecer dentro das tolerâncias definidas pelo fabricante do tracker e reproduzir o implantado no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, condição verificada por levantamento topográfico. O critério "Tolerâncias do fabricante conferidas (topografia)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois é o alinhamento das cravações e das estruturas que garante a continuidade geométrica do eixo de rotação e a compatibilidade entre fileiras adjacentes.',
  texto_risco_consequencia = 'Fileiras desalinhadas ou fora de prumo induzem esforços parasitas e desalinhamento do eixo de rotação, provocando desgaste prematuro de mancais e mecanismos, travamento do movimento do tracker, sombreamento entre fileiras e retrabalho de reposicionamento de estruturas já montadas. A permanência da condição mantém ativo o desvio geométrico até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente o alinhamento em planta e o prumo do trecho, confrontando com as tolerâncias do fabricante e o projeto executivo aprovado; (ii) corrigir a geometria realinhando e reaprumando as estruturas afetadas, ajustando a interface entre elementos até o restabelecimento das tolerâncias; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo levantamento topográfico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se conexões de elementos estruturais principais estiverem sem torque ou se o torquímetro empregado estiver sem certificado de calibração válido.',
  texto_fundamentacao_normativa = 'As conexões parafusadas devem ser apertadas segundo o mapa e os valores de torque especificados pelo fabricante do tracker, com torquímetro calibrado e certificado de calibração rastreável e dentro da validade, registrando-se a amostragem inspecionada. O critério "Torquímetro calibrado (certificado válido); amostragem registrada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, uma vez que o pré-tensionamento correto das juntas é o que assegura a manutenção do aperto sob as cargas de vento e as variações térmicas de operação. Aplica-se, ainda, o disposto no manual de montagem do fabricante e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'O torque incorreto — por sub ou sobreaperto — provoca afrouxamento das juntas sob carga cíclica de vento, dano por escoamento do parafuso ou esmagamento do perfil, com perda progressiva da integridade estrutural do conjunto e risco de deslocamento de componentes. Sem instrumento calibrado ou amostragem registrada, o aperto executado permanece sem comprovação metrológica. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o aperto das conexões conforme o mapa e os valores de torque do fabricante, utilizando torquímetro com certificado de calibração válido; (ii) registrar a amostragem inspecionada por fileira, identificando as juntas reprovadas e reapertadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a cópia do certificado de calibração do instrumento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de marcação impedir a rastreabilidade da inspeção de torque de conexões estruturais críticas ou a detecção posterior de afrouxamento.',
  texto_fundamentacao_normativa = 'A marcação de torque (torque mark) aplicada com caneta apropriada nas conexões já apertadas é o controle visual que evidencia que a junta foi efetivamente torqueada e que permite identificar, em inspeções futuras, eventual rotação/afrouxamento do conjunto parafuso-porca. O critério "Caneta de torque em conexões conferidas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, complementando o controle documental do aperto e conferindo rastreabilidade visual à etapa, conforme boas práticas de montagem e o manual do fabricante.',
  texto_risco_consequencia = 'Sem a marcação, perde-se a evidência visual de que a conexão foi torqueada, impossibilitando distinguir juntas conferidas das pendentes e dificultando a detecção de afrouxamentos durante a operação e a manutenção, o que pode mascarar não conformidades de aperto e retardar a resposta a falhas estruturais. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) aplicar a marcação de torque com caneta apropriada em todas as conexões efetivamente conferidas e aprovadas; (ii) confrontar as conexões marcadas com o mapa de torque do fabricante, sanando eventuais juntas sem marcação ou com marcação rompida; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a fixação inadequada comprometer a operação do atuador ou representar risco de queda de componentes ou de movimento descontrolado da estrutura.',
  texto_fundamentacao_normativa = 'O motor/atuador do tracker deve ser instalado conforme o manual do fabricante, com fixação, folgas e curso livre dentro das condições especificadas, garantindo o acoplamento correto ao mecanismo de acionamento. O critério "Fixação, folgas e curso livre" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois é a instalação conforme o manual que assegura o funcionamento do rastreamento sem interferências mecânicas e a preservação da vida útil do conjunto, em conformidade com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'O atuador instalado fora das condições do manual — com fixação frouxa, folgas incorretas ou curso obstruído — provoca falha ou imprecisão do rastreamento, sobrecarga e dano prematuro do mecanismo, paralisação da fileira e, no limite, risco de deslocamento ou queda de componentes durante a movimentação. A condição persiste até a reinstalação conforme o manual. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reinstalar o motor/atuador conforme o manual do fabricante, refazendo a fixação e conferindo o torque dos elementos de ancoragem; (ii) ajustar as folgas e verificar o curso livre em toda a amplitude de movimento, eliminando interferências; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o teste de movimentação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — condição de segurança elétrica; manter a RNC bloqueante até a comprovação de continuidade e da equipotencialização em toda a fileira, não admitindo liberação parcial.',
  texto_fundamentacao_normativa = 'O aterramento e a equipotencialização das estruturas metálicas do tracker devem ser executados de forma a garantir continuidade elétrica entre todos os segmentos, protegendo pessoas contra choque elétrico e assegurando o escoamento de correntes de falta e de descargas atmosféricas. Aplicam-se a NR-10 (segurança em instalações e serviços em eletricidade), a NBR 5410 (instalações elétricas de baixa tensão) e a NBR 16690 (instalações elétricas de arranjos fotovoltaicos), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Continuidade elétrica entre segmentos garantida" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A descontinuidade ou ausência de aterramento expõe trabalhadores e usuários a choque elétrico, impede o escoamento seguro de correntes de falta e de surtos de origem atmosférica e pode danificar equipamentos do arranjo fotovoltaico, configurando risco grave e iminente à segurança das pessoas e ao patrimônio. Enquanto não comprovada a continuidade, a estrutura permanece energizável sem proteção adequada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer e reapertar as conexões de aterramento e as juntas de equipotencialização entre segmentos, empregando conectores e cabos especificados; (ii) medir a continuidade elétrica entre os segmentos e a resistência de aterramento, confrontando com os valores de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o relatório de medição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a movimentação de teste indicar travamento, colisão entre fileiras ou falha na posição de segurança (stow) que exponha a estrutura a danos por vento.',
  texto_fundamentacao_normativa = 'O ajuste inicial do tracker compreende a configuração e a movimentação de teste realizadas pela interface do controlador (CM), conforme o procedimento de comissionamento do fabricante, verificando-se posições limite, sentido de rotação e acionamento da posição de segurança. O critério "Configuração e movimentação de teste (interface CM)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois é o ajuste inicial que valida a operação do rastreamento e a resposta do sistema aos comandos antes da entrada em operação, em conformidade com o manual do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'Um ajuste inicial incorreto resulta em rastreamento impreciso ou inoperante, impossibilidade de assumir a posição de segurança (stow) sob rajadas de vento, colisões entre fileiras adjacentes e perda de geração, além de expor a estrutura a esforços não previstos. A condição persiste até a reconfiguração e revalidação pela interface do controlador. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer a configuração e a movimentação de teste pela interface CM conforme o procedimento do fabricante, validando sentido de rotação e posições limite; (ii) verificar o acionamento correto da posição de segurança (stow) e a ausência de interferências ou colisões entre fileiras; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o registro do teste na interface do controlador, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a não conformidade final impedir a liberação/energização da fileira ou invalidar a garantia contratual do fabricante.',
  texto_fundamentacao_normativa = 'O atendimento às tolerâncias finais do fabricante, comprovado pelo preenchimento do checklist próprio por fileira, é a condição de aceitação que encerra a montagem e habilita a fileira às etapas subsequentes de comissionamento e energização, preservando as condições de garantia do equipamento. O critério "Checklist do fabricante preenchido por fileira" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, consolidando a conformidade geométrica e mecânica verificada nas etapas anteriores, em conformidade com o manual do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'Liberar a fileira sem a verificação e o registro das tolerâncias finais do fabricante mantém não conformidades documentais e defeitos latentes não tratados, com risco de perda da garantia contratual, reprovação em comissionamento e necessidade de retrabalho após a energização. Enquanto o checklist não for preenchido e as pendências sanadas, a etapa permanece sem aceitação formal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) preencher integralmente o checklist do fabricante para a fileira, registrando cada tolerância verificada; (ii) sanar as pendências identificadas (alinhamento, torque, folgas ou ajustes) e reconferir os pontos correspondentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o checklist assinado por fileira, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-01' and item_numero = 8;

-- ME-02 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se houver evidência de apoio indevido, flexão ou pisoteio sobre módulos já manuseados, e a Crítica se o esforço mecânico indevido resultar em microfissuras ou trincas de célula',
  texto_fundamentacao_normativa = 'O manuseio, transporte e içamento dos módulos fotovoltaicos deve seguir estritamente o manual de instalação do fabricante, que estabelece pontos de apoio, orientação de carga e proibições de esforço mecânico sobre o laminado. Módulos fotovoltaicos são componentes sensíveis a microfissuras: apoio pontual, flexão do quadro ou pisoteio sobre a superfície geram tensões que degradam as células mesmo sem dano visível. Na ausência de norma técnica específica que regule o gesto de manuseio, aplicam-se o manual do fabricante, o procedimento de movimentação da obra e as boas práticas de execução, alinhados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem apoio indevido, flexão ou pisoteio de módulos" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'O manuseio em desacordo com o manual induz microfissuras e trincas ocultas nas células, que não são detectáveis a olho nu e reduzem a geração ao longo da vida útil do módulo, além de antecipar falhas e perda de garantia do fabricante. A permanência da prática incorreta multiplica o número de módulos comprometidos antes de qualquer triagem, elevando o passivo de desempenho do arranjo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender imediatamente o manuseio em desacordo e requalificar a equipe quanto aos pontos de apoio, ao número mínimo de operadores e às proibições estabelecidas no manual do fabricante; (ii) segregar e submeter à inspeção os módulos que sofreram apoio indevido, flexão ou pisoteio, priorizando ensaio de eletroluminescência quando disponível para detectar microfissuras; (iii) evidenciar a correção com registro fotográfico do procedimento adequado de manuseio e a triagem dos módulos afetados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando vidro trincado, backsheet perfurado ou caixa de junção danificada não forem registrados e o módulo comprometido for instalado no arranjo',
  texto_fundamentacao_normativa = 'A inspeção visual no recebimento e na instalação deve verificar a integridade do vidro frontal, do backsheet e da caixa de junção de cada módulo, com registro formal de quebras e avarias, condição estabelecida pelo manual do fabricante e pelo procedimento de recebimento de materiais da obra. A caixa de junção e o backsheet garantem a estanqueidade e o isolamento elétrico do módulo; falhas nesses componentes comprometem a segurança e a durabilidade do sistema. Na ausência de número normativo específico que se aplique diretamente a este ensaio de recebimento, a fundamentação apoia-se no manual do fabricante, nas boas práticas de controle de recebimento e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Vidro, backsheet e caixa de junção íntegros; quebras registradas" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A instalação de módulos com vidro trincado, backsheet perfurado ou caixa de junção danificada, sem registro da avaria, permite a entrada de umidade, a perda de isolamento e a formação de pontos quentes, com risco de arco elétrico, incêndio e degradação acelerada, além de inviabilizar o acionamento de garantia por não haver rastreabilidade do dano de origem. A ausência de registro transfere para a operação um passivo oculto de módulos comprometidos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reinspecionar visualmente o lote recebido e o instalado, identificando módulos com vidro, backsheet ou caixa de junção não íntegros; (ii) segregar e registrar formalmente as avarias, bloqueando a instalação dos módulos comprometidos e acionando a substituição junto ao fornecedor; (iii) evidenciar a correção com registro fotográfico das peças avariadas e do relatório de não conformidade de recebimento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando clamps fora da zona de fixação ou com torque incorreto comprometerem a fixação mecânica do módulo à estrutura, com risco de arrancamento sob carga de vento',
  texto_fundamentacao_normativa = 'Os grampos de fixação (clamps) devem ser posicionados exclusivamente na zona de fixação e aplicados com o torque definidos no manual do fabricante do módulo, parâmetros que integram a validação estrutural da fixação frente às cargas de vento e neve consideradas no projeto. Clamp fora da zona permitida transfere esforço para região não dimensionada do laminado, e torque insuficiente ou excessivo compromete a ancoragem ou danifica o quadro. Na ausência de número normativo específico que fixe estes valores, a fundamentação apoia-se no manual do fabricante, no projeto de fixação estrutural e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Zona de fixação e torque do manual atendidos" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Clamps posicionados fora da zona de fixação ou com torque em desacordo com o manual comprometem a ancoragem mecânica do módulo, podendo provocar folga, deformação do quadro ou arrancamento sob carga de vento, com risco de queda de módulos, dano a terceiros e interrupção da geração. A condição mantém a fixação subdimensionada até a correção, expondo o arranjo a solicitações que ele não foi verificado para resistir. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir a posição de todos os clamps frente à zona de fixação admissível do manual, reposicionando os que estiverem fora; (ii) reaplicar o torque com torquímetro calibrado nos valores do manual, registrando os valores obtidos por amostragem representativa; (iii) evidenciar a correção com registro fotográfico da fixação e do aferimento de torque ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de serialização impedir a rastreabilidade de módulos para fins de garantia, comissionamento ou identificação de falhas por string',
  texto_fundamentacao_normativa = 'O número de série de cada módulo deve ser registrado e vinculado à respectiva string/fileira, constituindo a rastreabilidade que dá suporte ao comissionamento, ao acionamento de garantia e à investigação de falhas por posição no arranjo. Sem esse vínculo, um módulo defeituoso não pode ser localizado nem sua garantia comprovada. Trata-se de requisito documental de rastreabilidade, fundamentado no plano da qualidade da obra, no procedimento de as-built e nas boas práticas de gestão de ativos, em conformidade com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; não se cita número normativo por não haver norma técnica específica que o determine para este registro. O critério "Nº de série vinculado a string/fileira (rastreabilidade)" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A falta de serialização vinculada à string impede localizar fisicamente um módulo com defeito, inviabiliza a comprovação de garantia perante o fabricante e dificulta a análise de causa de perdas de geração por posição no arranjo, transferindo para a operação um sistema sem histórico rastreável. Quanto mais avança a montagem sem o registro, maior o esforço de levantamento retroativo em campo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar em campo os números de série dos módulos já instalados sem registro, associando-os às strings/fileiras correspondentes; (ii) consolidar a serialização no as-built e no sistema de rastreabilidade da obra, corrigindo divergências entre o instalado e o documentado; (iii) evidenciar a correção com registro fotográfico das etiquetas de série e da planilha de vínculo módulo-string atualizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que houver inversão de polaridade ou sequência de string em desacordo com o projeto elétrico, pela exposição a dano de equipamento e risco elétrico',
  texto_fundamentacao_normativa = 'As strings devem ser conectadas com a polaridade e a sequência definidas no projeto elétrico, com etiquetagem de identificação aplicada, de modo que a tensão de circuito aberto e a configuração série/paralelo correspondam ao dimensionado para o inversor e para os dispositivos de proteção. Inversão de polaridade ou sequência incorreta submete equipamentos a condições fora de projeto. Aplicam-se a NBR 16690 (instalações elétricas de arranjos fotovoltaicos — requisitos de projeto) e a NBR 5410 (instalações elétricas de baixa tensão), além do projeto elétrico executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem a configuração e a identificação dos circuitos. O critério "Conforme projeto elétrico; etiquetagem aplicada" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'String com polaridade invertida ou sequência incorreta pode danificar o inversor e os diodos de bypass, provocar sobretensão nos condutores, acionamento indevido de proteções e risco de arco elétrico, além de comprometer a geração e a segurança da equipe de comissionamento. A ausência de etiquetagem correta agrava o risco ao dificultar o seccionamento seguro em manutenção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar polaridade e tensão de circuito aberto de cada string com instrumento adequado, antes da energização, confrontando com o projeto elétrico; (ii) corrigir as conexões invertidas ou fora de sequência e aplicar a etiquetagem de identificação de polaridade e string conforme projeto; (iii) evidenciar a correção com registro fotográfico das conexões, das medições de polaridade e das etiquetas aplicadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que a continuidade de aterramento dos módulos não estiver garantida, por se tratar de proteção contra choque elétrico e falha à terra',
  texto_fundamentacao_normativa = 'O aterramento dos módulos deve ser garantido pela fixação com dispositivos de contato elétrico (WEEB/clip de aterramento) ou por condutor de equipotencialização, conforme o projeto, assegurando a continuidade da massa metálica dos quadros até o barramento de terra. Esse caminho de baixa impedância é o que permite a atuação das proteções e limita a tensão de contato em caso de falha de isolamento. Aplicam-se a NBR 16690 (instalações elétricas de arranjos fotovoltaicos — requisitos de projeto), a NBR 5410 (instalações elétricas de baixa tensão, aterramento e equipotencialização) e a NR-10 (segurança em instalações e serviços em eletricidade), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Clamps com WEEB/condutor conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A falha na continuidade do aterramento dos módulos deixa a estrutura e os quadros metálicos energizáveis em caso de falha de isolamento, expondo pessoas a choque elétrico e impedindo a atuação correta das proteções contra falta à terra, além de agravar danos por descargas atmosféricas. Enquanto não corrigida, a condição mantém a instalação com proteção de segurança comprometida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar os pontos de aterramento dos módulos, verificando a presença e o assentamento correto dos WEEB/clips ou do condutor de equipotencialização conforme projeto; (ii) restabelecer a continuidade nos pontos deficientes e comprovar por medição de continuidade/resistência de aterramento os valores admissíveis; (iii) evidenciar a correção com registro fotográfico dos dispositivos de aterramento e do laudo de medição de continuidade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor quando o índice de quebras por lote/contratada não for controlado, e a Maior se o índice ultrapassar o limite contratual/de projeto sem plano de ação',
  texto_fundamentacao_normativa = 'O índice de quebras e avarias de módulos deve ser controlado por meio de relatório periódico segregado por lote e por contratada, permitindo identificar tendências, atribuir causas de manuseio ou logística e acionar ações preventivas antes que o passivo cresça. Trata-se de indicador de gestão da qualidade, fundamentado no plano da qualidade da obra, no procedimento de controle de avarias e nas boas práticas de gestão de suprimentos, alinhado ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; não se cita número normativo por não haver norma técnica específica que estabeleça este índice. O critério "Relatório de avarias por lote/contratada" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de controle do índice de quebras por lote e contratada impede identificar a causa-raiz das avarias, seja de transporte, armazenamento ou manuseio, e permite que perdas recorrentes se acumulem sem tratamento, com impacto de custo, de prazo de reposição e de disponibilidade de módulos para conclusão do arranjo. Sem o indicador, a reincidência só é percebida quando o passivo já é relevante. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar ou atualizar o relatório de avarias, consolidando as quebras por lote e por contratada com data, quantidade e causa provável; (ii) analisar as tendências e acionar ações preventivas sobre as etapas de maior incidência (transporte, armazenamento ou manuseio), definindo limite de aceitação; (iii) evidenciar a correção com registro fotográfico do relatório consolidado e do plano de ação sobre as causas identificadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-02' and item_numero = 7;

-- ME-03 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que o içamento envolver carga classificada como crítica sem plano de rigging aprovado; reduzir a Maior apenas se o plano existir e assinado, restando pendência documental de menor monta (ex.: cópia não anexada ao dossiê da operação).',
  texto_fundamentacao_normativa = 'Toda operação de içamento de carga crítica deve ser precedida de plano de rigging específico, aprovado e assinado por profissional legalmente habilitado, com a respectiva Anotação de Responsabilidade Técnica (ART), demonstrando que a relação carga × capacidade do conjunto atende ao fator de segurança adotado. Aplica-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais), que exige procedimento e responsável técnico para a movimentação de cargas, somada ao plano de transporte/içamento da obra e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no que define pesos, pontos de içamento e interferências. O critério "assinado por profissional habilitado; carga × capacidade ≥ fator" integra o plano de inspeção da obra e constitui requisito verificável de liberação da operação.',
  texto_risco_consequencia = 'Executar içamento de carga crítica sem plano de rigging aprovado suprime a verificação prévia de estabilidade, capacidade e fator de segurança do conjunto, expondo a operação a tombamento do equipamento de içamento, ruptura de acessórios e queda da carga, com risco de acidente grave ou fatal, danos materiais de alto valor e paralisação da frente. A permanência da condição mantém a operação sem cobertura técnica formal até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a operação de içamento até a emissão do plano de rigging específico, assinado por profissional habilitado e amparado por ART; (ii) demonstrar no plano a relação carga × capacidade ≥ fator de segurança adotado, considerando raio de operação, ângulo e acessórios; (iii) evidenciar a aprovação e a disponibilização do plano na frente de serviço ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o equipamento estiver em operação com ART ausente, inspeção vencida ou não conformidade estrutural/mecânica identificada; manter Maior se a pendência for exclusivamente documental com laudo válido em vias de anexação.',
  texto_fundamentacao_normativa = 'Os equipamentos de içamento (guindaste, caminhão munck e similares) devem operar com Anotação de Responsabilidade Técnica (ART) e laudos de inspeção periódica válidos, comprovando a integridade estrutural e mecânica e a aptidão para a carga de projeto. Aplicam-se a NR-11 e a NR-12 (segurança no trabalho em máquinas e equipamentos), que exigem inspeção, manutenção e responsável técnico para máquinas de elevação, observada a interface com o item ST-04 (verificação de laudos e documentação dos equipamentos). O critério "guindaste/munck com ART e inspeção válidas" constitui requisito verificável de aceitação prévia à mobilização do equipamento na operação.',
  texto_risco_consequencia = 'Empregar equipamento de içamento sem ART ou com inspeção vencida remove a garantia formal de que o guindaste ou munck está apto e íntegro para a carga prevista, elevando a probabilidade de falha estrutural (lança, cabos, roldanas) ou mecânica (sistema hidráulico, freios) durante a manobra, com queda de carga, danos e risco à integridade dos trabalhadores no raio de operação. A permanência da condição mantém o equipamento operando sem respaldo técnico até a apresentação da documentação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar o equipamento de operação até a apresentação da ART e dos laudos de inspeção válidos, em coerência com o item ST-04; (ii) confirmar por inspeção visual e documental a integridade de cabos, lança, ganchos e sistemas de segurança, sanando eventuais restrições apontadas nos laudos; (iii) evidenciar a documentação regularizada e a condição do equipamento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a amarração incorreta ocorrer em carga crítica ou empregar pontos não previstos pelo fabricante; manter Maior para desvios de amarração em cargas não críticas prontamente corrigíveis.',
  texto_fundamentacao_normativa = 'A amarração da carga deve reproduzir integralmente o plano de rigging, respeitando os pontos de pega (olhais, orelhas de içamento e apoios) definidos pelo fabricante do equipamento, que dimensiona esses pontos para os esforços de elevação. O uso de acessórios (cintas, manilhas, balancins) deve ser compatível com a carga e os ângulos previstos. Fundamentam este requisito o manual/desenho do fabricante do equipamento, o plano de rigging aprovado e a NR-11, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto a interferências e sequência de montagem. O critério "pontos de pega do fabricante respeitados" é requisito verificável imediatamente antes do tensionamento dos acessórios.',
  texto_risco_consequencia = 'Amarrar a carga fora dos pontos de pega do fabricante ou em desacordo com o plano introduz esforços não previstos na peça e nos acessórios, podendo provocar escorregamento da carga, deformação ou dano ao equipamento içado, ruptura de cinta/manilha e queda, com risco de acidente e comprometimento da própria peça a ser montada. A permanência da condição mantém o arranjo de içamento em configuração não validada até sua correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer a amarração exclusivamente nos pontos de pega indicados pelo fabricante e conforme o plano de rigging aprovado; (ii) verificar a compatibilidade de cintas, manilhas e balancim com a carga e os ângulos de içamento, substituindo acessórios inadequados; (iii) evidenciar o arranjo de amarração corrigido antes da elevação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o registrador de impacto acusar aceleração acima do limite especificado pelo fabricante ou se o transporte ocorrer sem monitoramento; manter Maior para desvios de rota/velocidade sem indício de impacto relevante.',
  texto_fundamentacao_normativa = 'O transporte de transformador deve ser controlado por registrador de impacto (impact recorder) e por rota e velocidade previamente definidas, de modo a manter as acelerações dentro dos limites tolerados pelo equipamento e preservar sua integridade interna e a garantia do fabricante. Na ausência de norma específica aplicável de forma inequívoca a este controle, o requisito fundamenta-se na especificação técnica e no manual do fabricante do transformador, no plano de transporte da obra e nas boas práticas de logística de cargas sensíveis, articulados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "registrador de impacto; rota e velocidade definidas" constitui requisito verificável de aceitação da etapa de transporte.',
  texto_risco_consequencia = 'Transportar o transformador sem registrador de impacto ativo ou fora da rota e velocidade definidas impede a comprovação de que o equipamento não sofreu solicitações acima do tolerado, podendo mascarar danos internos (deslocamento de núcleo/enrolamentos, avaria em buchas) que somente se manifestariam na energização, além de ensejar recusa de garantia pelo fabricante e retrabalho de reparo ou substituição de item de alto valor. A permanência da condição mantém indefinida a condição de integridade do transformador até verificação adequada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) assegurar registrador de impacto instalado e ativo durante todo o transporte, com rota e velocidade conforme o plano aprovado; (ii) analisar os registros de aceleração ao término do trajeto e, havendo indício de impacto acima do limite do fabricante, acionar inspeção técnica antes da instalação; (iii) evidenciar os registros do dispositivo e as condições de transporte ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de locação ou nivelamento comprometer a interface com conexões, barramentos, tubulações ou o alinhamento de conjuntos acoplados; manter Maior para desvios dentro de faixa corrigível por calços/ajuste.',
  texto_fundamentacao_normativa = 'O posicionamento do equipamento sobre a base deve atender às tolerâncias de locação e de nivelamento definidas em projeto e pelo fabricante, condição verificada por instrumento topográfico/nível, assegurando a correta transferência de cargas à fundação e o alinhamento com as interfaces de montagem. Fundamentam o requisito o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, o desenho de implantação e as tolerâncias de nivelamento do manual do fabricante, complementados pelas boas práticas de montagem eletromecânica. O critério "tolerâncias de locação/nivelamento atendidas" integra o plano de inspeção e constitui requisito verificável de aceitação do posicionamento.',
  texto_risco_consequencia = 'Posicionar o equipamento fora das tolerâncias de locação e nivelamento induz esforços indevidos na base e no próprio equipamento, desalinhamento de conexões elétricas e mecânicas, vibração excessiva e desgaste prematuro, podendo exigir reposicionamento com movimentação adicional de carga e impacto de cronograma, além de comprometer o desempenho e a vida útil do conjunto. A permanência da condição mantém ativo o desvio geométrico da instalação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir por topografia/nível a locação e o nivelamento do equipamento, confrontando com as tolerâncias de projeto e do fabricante; (ii) corrigir o posicionamento por ajuste, calços ou reposicionamento controlado, restabelecendo o atendimento às tolerâncias e o alinhamento das interfaces; (iii) evidenciar a correção com registro fotográfico e novo levantamento/medição de nível ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a supervisão do fabricante for condição contratual de preservação da garantia e a atividade avançar sem ela; manter Maior se a presença tiver ocorrido mas faltar o registro formal correspondente.',
  texto_fundamentacao_normativa = 'Quando a especificação contratual ou o manual do fabricante exigirem supervisão (comissionamento assistido) durante a montagem ou o posicionamento do equipamento, essa presença deve ser efetiva e formalmente registrada, uma vez que dela depende, em regra, a preservação da garantia do fornecedor. Na ausência de norma técnica que imponha genericamente essa exigência, o requisito fundamenta-se na especificação técnica do fornecimento, nas condições contratuais de garantia e no manual do fabricante, articulados às boas práticas de montagem eletromecânica. O critério "presença registrada (garantia preservada)" constitui requisito verificável de aceitação da etapa em que a supervisão é exigida.',
  texto_risco_consequencia = 'Executar a atividade sem a supervisão do fabricante, quando exigida, ou sem seu registro formal, pode ensejar a perda ou o questionamento da garantia contratual do equipamento e a ausência de validação técnica de montagem por quem detém o conhecimento do produto, transferindo à obra o risco integral por eventuais defeitos e por reparos de alto custo. A permanência da condição mantém a etapa sem o respaldo técnico do fornecedor até a devida regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar na especificação e no contrato as etapas em que a supervisão do fabricante é exigida e assegurar sua presença efetiva antes de prosseguir; (ii) formalizar o registro da supervisão (relatório/ata assinada pelo representante do fabricante) vinculando-o às atividades acompanhadas; (iii) evidenciar a presença e o registro da supervisão ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-03' and item_numero = 6;

-- ME-04 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a junta for de responsabilidade estrutural ou de contenção de pressão e a soldagem estiver sendo executada sem EPS aplicável disponível na frente de serviço.',
  texto_fundamentacao_normativa = 'A Especificação de Procedimento de Soldagem (EPS) qualificada deve estar fisicamente disponível na frente de serviço para que o soldador execute a junta dentro das variáveis essenciais qualificadas (material de base, faixa de espessura, processo, metal de adição, posição e gás/fluxo). A qualificação e o uso de procedimentos de soldagem apoiam-se em códigos consagrados de fabricação — ASME BPVC Seção IX e ABNT NBR ISO 15614-1 — e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define materiais e detalhes de junta. O critério "Procedimento compatível com material e junta" integra o plano de inspeção da obra e constitui requisito verificável de liberação da atividade.',
  texto_risco_consequencia = 'Soldar sem a EPS aplicável disponível na frente permite a adoção de parâmetros fora da faixa qualificada, com risco de descontinuidades, propriedades metalúrgicas inadequadas e reprovação em END, exigindo reparo ou refação da junta com sobrecusto e atraso. A permanência da condição mantém a atividade sem rastreabilidade de procedimento até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a soldagem do trecho e disponibilizar na frente a EPS qualificada e compatível com o material e a junta, conferindo suas variáveis essenciais; (ii) confrontar a EPS com o projeto executivo aprovado e o mapa de juntas, confirmando aplicabilidade a espessura, posição e processo; (iii) evidenciar a correção com registro fotográfico da EPS na frente e das juntas liberadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando soldador sem RQPS válido houver executado juntas já concluídas de responsabilidade estrutural ou de pressão, exigindo reavaliação retroativa das soldas.',
  texto_fundamentacao_normativa = 'Cada soldador deve possuir Registro de Qualificação de Performance de Soldador (RQPS) válido e abrangente para o processo, a posição e a faixa qualificada da junta que executa, assegurando destreza comprovada por ensaio. A qualificação de soldadores apoia-se em normas reconhecidas — ABNT NBR ISO 9606-1 e ASME BPVC Seção IX — que definem variáveis essenciais e prazo de validade da qualificação. O critério "RQPS válido para o processo/posição" integra o plano de inspeção e constitui requisito verificável de habilitação da mão de obra para a atividade.',
  texto_risco_consequencia = 'Executar solda com soldador sem RQPS válido para o processo/posição eleva a probabilidade de descontinuidades (falta de fusão, penetração inadequada, porosidade) e compromete a rastreabilidade da mão de obra, podendo invalidar as juntas produzidas e obrigar a reparo ou refação com retrabalho e atraso. A permanência da condição mantém soldas de habilitação não comprovada incorporadas à obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar da atividade o soldador sem RQPS válido e substituí-lo por profissional com qualificação vigente e abrangente ao processo e à posição; (ii) levantar as juntas já executadas pelo profissional não habilitado e submetê-las a END adicional conforme mapa de juntas, promovendo a qualificação/renovação do RQPS quando cabível; (iii) evidenciar a correção com cópia dos RQPS válidos e registro fotográfico das frentes regularizadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em consumíveis de baixo hidrogênio (eletrodos básicos) fora do controle de estufa/cartucheira aplicados em aços suscetíveis a trinca a frio.',
  texto_fundamentacao_normativa = 'Os consumíveis de soldagem (eletrodos, arames, fluxos) devem ser controlados quanto à ressecagem e à manutenção em estufa e cartucheira nas temperaturas e tempos recomendados pelo fabricante, com rastreabilidade de lote que vincule o consumível à junta e à EPS. A exigência decorre das instruções do fabricante do consumível, das variáveis definidas na EPS aplicável e das boas práticas de controle de hidrogênio difusível em soldagem. O critério "Estufa/cartucheira; rastreabilidade de lote" integra o plano de inspeção e constitui requisito verificável de aceitação dos insumos empregados.',
  texto_risco_consequencia = 'Consumíveis sem controle de ressecagem e sem rastreabilidade de lote absorvem umidade e introduzem hidrogênio no cordão, favorecendo porosidade e trinca a frio induzida por hidrogênio, além de impedir a identificação de lotes não conformes já aplicados. A permanência da condição mantém insumos de qualidade não assegurada incorporados às juntas até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher os consumíveis fora de controle, restabelecer estufa e cartucheira nas temperaturas/tempos do fabricante e segregar lotes vencidos ou expostos à umidade; (ii) reinstituir o registro de rastreabilidade de lote vinculando consumível, EPS e junta, avaliando por END as soldas executadas com material suspeito; (iii) evidenciar a correção com registro fotográfico das estufas/cartucheiras em operação e das etiquetas de lote ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de preparação (ângulo de bisel, abertura de raiz ou contaminação) comprometer a penetração de raiz de junta soldada de pressão ou estrutural.',
  texto_fundamentacao_normativa = 'A preparação da junta — ângulo de bisel, abertura de raiz, face de raiz, alinhamento e limpeza — deve reproduzir a geometria e as condições definidas na EPS aplicável, pois são variáveis que condicionam a fusão e a sanidade do cordão. A exigência decorre da própria EPS qualificada, dos códigos de fabricação de referência (ASME BPVC Seção IX / ABNT NBR ISO 15614-1) e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Bisel, abertura e limpeza conferidos" integra o plano de inspeção e constitui requisito verificável antes da liberação para soldagem.',
  texto_risco_consequencia = 'Junta preparada em desacordo com a EPS (bisel, abertura ou limpeza inadequados, presença de óxidos, óleo ou umidade) gera falta de fusão, falta de penetração, inclusões e porosidade, com reprovação em END e necessidade de reparo. A permanência da condição transfere o defeito de preparação para o cordão executado, ampliando o retrabalho até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir a geometria de preparação (ângulo de bisel, abertura de raiz, face e alinhamento) contra a EPS e o projeto, corrigindo por novo chanfro/ajuste o que estiver fora; (ii) executar a limpeza da junta e da região adjacente, removendo óxidos, óleo, umidade e resíduos antes de liberar a soldagem; (iii) evidenciar a correção com registro fotográfico da junta preparada e conferida ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que o percentual de END exigido pelo projeto não for atendido; rebaixar a Maior apenas em pendência exclusivamente documental (ensaio realizado, relatório não arquivado).',
  texto_fundamentacao_normativa = 'Os ensaios não destrutivos (LP, PM, UT e RX) devem ser executados no percentual e nos métodos definidos pelo mapa de juntas do projeto, com relatórios arquivados que comprovem a aceitação de cada junta. A exigência decorre do plano de END e do mapa de juntas do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, complementados pelas boas práticas de controle da qualidade de juntas soldadas. O critério "LP/PM/UT/RX conforme mapa de juntas; relatórios arquivados" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa de soldagem.',
  texto_risco_consequencia = 'Deixar de executar os END no percentual do projeto, ou não arquivar seus relatórios, impede a comprovação da sanidade interna e superficial das juntas, permitindo que descontinuidades críticas permaneçam ocultas e cheguem à operação com risco de falha estrutural ou vazamento sob pressão. A permanência da condição mantém juntas com aceitação não comprovada incorporadas à obra até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar as juntas executadas com o mapa de juntas e completar os END faltantes (LP/PM/UT/RX) no percentual e métodos exigidos pelo projeto; (ii) organizar e arquivar os relatórios de END com identificação da junta, do soldador e do resultado, tratando por reparo as juntas reprovadas; (iii) evidenciar a correção com os relatórios de END e registro fotográfico do arquivamento/ensaios ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica enquanto houver junta reparada sem novo END que comprove a aceitação; rebaixar a Maior apenas quando o ensaio de reinspeção já existir e faltar somente seu registro/arquivo.',
  texto_fundamentacao_normativa = 'Toda junta submetida a reparo deve ser reinspecionada por novo END, com registro que comprove a eliminação da descontinuidade que motivou o reparo, uma vez que a região reparada não herda a aceitação do ensaio original. A exigência decorre do plano de END e do mapa de juntas do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e das boas práticas de tratamento de não conformidade em soldagem. O critério "Junta reparada com novo END registrado" integra o plano de inspeção e constitui requisito verificável para o fechamento de reparos.',
  texto_risco_consequencia = 'Reparo não reinspecionado por novo END pode manter ou introduzir descontinuidades na região retrabalhada sem qualquer comprovação de sanidade, levando defeitos ocultos à operação com risco de falha justamente na zona já identificada como fragilizada. A permanência da condição mantém reparos de eficácia não comprovada incorporados à obra até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar todas as juntas reparadas e submeter cada uma a novo END pelo método aplicável (LP/PM/UT/RX), conforme o defeito original e o mapa de juntas; (ii) registrar e arquivar o resultado da reinspeção vinculando-o à junta e ao reparo, reprocessando as que persistirem reprovadas; (iii) evidenciar a correção com os relatórios de END de reinspeção e registro fotográfico das juntas reparadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de atualização do livro de solda impedir a rastreabilidade de juntas de responsabilidade estrutural ou de pressão, ou a liberação documental da etapa.',
  texto_fundamentacao_normativa = 'O livro (ou registro) de solda deve ser mantido atualizado, correlacionando cada junta ao soldador, à EPS empregada e aos END realizados, assegurando rastreabilidade completa do histórico de fabricação. A exigência decorre das boas práticas de gestão da qualidade em soldagem e da necessidade de rastreabilidade prevista no plano de inspeção da obra e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Rastreabilidade junta × soldador × EPS × END" constitui requisito verificável de organização documental da etapa.',
  texto_risco_consequencia = 'Livro de solda desatualizado rompe a cadeia de rastreabilidade junta × soldador × EPS × END, dificultando a identificação de juntas afetadas em caso de reprovação de lote, consumível ou soldador, e comprometendo a comprovação documental exigida no data-book e no as-built. A permanência da condição mantém a etapa sem rastreabilidade auditável até a regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) atualizar o livro de solda registrando, para cada junta, o soldador, a EPS aplicada e os END realizados, com respectivas identificações e datas; (ii) conciliar os lançamentos com o mapa de juntas e os relatórios de END, sanando lacunas e divergências identificadas; (iii) evidenciar a correção com registro fotográfico do livro de solda atualizado e conciliado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que houver trabalho a quente em execução sem Permissão de Trabalho válida ou sem atendimento à interface ST-13, dado o risco imediato de incêndio.',
  texto_fundamentacao_normativa = 'A execução de trabalho a quente (soldagem, corte, esmerilhamento) exige Permissão de Trabalho (PT) emitida e válida, com atendimento à interface ST-13, que consolida as medidas de prevenção de incêndio, isolamento de inflamáveis, vigia de fogo e disponibilidade de combate a incêndio. A exigência decorre da própria interface ST-13, do procedimento de PT da obra e das boas práticas de segurança do trabalho para atividades geradoras de fonte de ignição. O critério "Interface ST-13 atendida" constitui requisito verificável e condição de liberação da atividade a quente.',
  texto_risco_consequencia = 'Realizar trabalho a quente sem PT válida e sem atender à interface ST-13 expõe a frente a princípio de incêndio e explosão por projeção de fagulhas e respingos sobre materiais combustíveis ou atmosferas inflamáveis, com risco imediato à integridade física dos trabalhadores e ao patrimônio da obra. A permanência da condição mantém ativo o risco de ignição não controlado até o efetivo atendimento dos controles. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper imediatamente o trabalho a quente e só reiniciar mediante Permissão de Trabalho válida, com a interface ST-13 integralmente atendida; (ii) implementar as medidas de controle exigidas — isolamento e proteção de inflamáveis, vigia de fogo, extintores e sinalização da área — antes de reautorizar a atividade; (iii) evidenciar a correção com a PT emitida e registro fotográfico das medidas de prevenção de incêndio na frente ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-04' and item_numero = 8;

-- ME-05 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desnível ou o assentamento inadequado da base comprometer o alinhamento subsequente, a ancoragem ou a integridade estrutural do equipamento em operação.',
  texto_fundamentacao_normativa = 'O correto assentamento e nivelamento da base é condição de partida da montagem mecânica, pois define o plano de referência para alinhamento, ancoragem e transmissão de esforços do equipamento à fundação. O desenho certificado do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} estabelecem tolerâncias de planicidade e nivelamento, cotas de chumbadores e detalhamento do grauteamento. O critério "Conforme desenho certificado do fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, aferido por nível de precisão/topografia antes da liberação das etapas seguintes.',
  texto_risco_consequencia = 'Base fora de nível ou mal assentada induz desalinhamento permanente, sobrecarga em chumbadores e mancais, vibração excessiva e desgaste prematuro do equipamento, podendo exigir desmontagem e reexecução do grauteamento com sobrecusto e atraso. A permanência da condição mantém ativo o desvio de fundação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reaferir o nivelamento e as cotas da base com nível de precisão/topografia, confrontando com o desenho certificado do fabricante e o projeto executivo aprovado; (ii) corrigir a condição (recalço, reajuste de calços/parafusos de nivelamento ou refazer o grauteamento, conforme o caso), restabelecendo as tolerâncias especificadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo relatório de nivelamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em conjuntos rotativos de alta rotação ou potência, ou quando o desalinhamento exceder a tolerância do fabricante ao ponto de risco a mancais e acoplamento.',
  texto_fundamentacao_normativa = 'O alinhamento de acoplamentos entre máquina motora e movida deve respeitar as tolerâncias de desvio angular e paralelo definidas pelo manual do fabricante, sendo comprovado por relatório de alinhamento (relógio comparador ou laser) quando aplicável. O projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e a documentação técnica do equipamento estabelecem os valores admissíveis. O critério "Relatório de alinhamento quando aplicável" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a liberação para acoplamento definitivo e teste em vazio.',
  texto_risco_consequencia = 'Acoplamento desalinhado gera esforços cíclicos sobre eixos, mancais, selos e elementos elásticos, provocando vibração, aquecimento, fadiga e falha prematura do conjunto rotativo, com risco de parada não programada e dano a equipamento de custo elevado. A permanência da condição mantém ativa a solicitação anormal do trem de acionamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar novo alinhamento por relógio comparador ou laser, com correção de pé manco (soft foot) e uso de calços calibrados, atendendo às tolerâncias do manual do fabricante; (ii) reapertar o acoplamento e reconferir os desvios angular e paralelo a frio, prevendo compensação de crescimento térmico quando indicado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e emitir/atualizar o relatório de alinhamento assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em flanges de serviços críticos (alta pressão, temperatura, fluidos inflamáveis ou tóxicos) ou quando o aperto fora do mapa e da sequência cruzada comprometer a estanqueidade da junta.',
  texto_fundamentacao_normativa = 'O aperto de flanges deve seguir o mapa de torque especificado e a sequência cruzada em passes escalonados, com emprego da junta correta (material, dimensão e classe de pressão), garantindo distribuição uniforme de carga e o esmagamento adequado do elemento de vedação. O mapa de torque, a folha de dados do equipamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} definem os valores e a especificação das juntas. O critério "Sequência cruzada; juntas corretas" integra o plano de inspeção e constitui requisito verificável de aceitação da junta flangeada, condicionando a liberação para teste de estanqueidade.',
  texto_risco_consequencia = 'Flange apertado fora do mapa, sem sequência cruzada ou com junta incorreta resulta em distribuição desigual de carga, esmagamento inadequado da junta e afrouxamento em operação, gerando vazamento de fluido do processo com risco à segurança, ao meio ambiente e à continuidade operacional. A permanência da condição mantém ativo o risco de perda de estanqueidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a especificação e o estado da junta, substituindo-a por elemento correto e novo sempre que houver reabertura da conexão; (ii) reapertar os parafusos com torquímetro calibrado, em passes progressivos e sequência cruzada, conforme o mapa de torque aprovado, registrando os valores finais; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o mapa de torque preenchido, submetendo à reinspeção e ao teste de estanqueidade para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência, o tipo incorreto ou a quantidade inadequada de lubrificante puder causar dano a mancais e engrenagens na primeira partida do equipamento.',
  texto_fundamentacao_normativa = 'A lubrificação inicial deve reproduzir estritamente o manual do fabricante quanto ao tipo, especificação e quantidade de lubrificante, condição de partida segura para mancais, engrenagens e demais componentes de contato. O manual do equipamento e a folha de dados definem o produto e o volume/nível corretos; o registro de tipo e quantidade constitui rastreabilidade da atividade. O critério "Tipo e quantidade de lubrificante registrados" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a liberação do equipamento para energização e teste.',
  texto_risco_consequencia = 'Equipamento operado com lubrificante ausente, incompatível ou em quantidade incorreta sofre lubrificação deficiente, elevando atrito, temperatura e desgaste, com risco de gripagem e falha catastrófica de mancais e engrenagens já na partida, além de perda de garantia do fabricante. A permanência da condição mantém ativo o risco de dano por lubrificação inadequada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar tipo, especificação e quantidade do lubrificante frente ao manual do fabricante, corrigindo produto e nível/volume conforme prescrito; (ii) drenar e substituir lubrificante incorreto ou contaminado quando aplicável, verificando visores, bujões e pontos de graxa; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a ficha de lubrificação com tipo e quantidade registrados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando resíduos internos ou perda de estanqueidade puderem migrar para o processo, danificar componentes internos ou comprometer o teste de circuitos críticos.',
  texto_fundamentacao_normativa = 'A limpeza interna e a estanqueidade asseguram que tubulações e circuitos internos estejam isentos de sujidade, cavaco, escória e corpos estranhos, e que as vedações resistam à pressão de serviço, sendo os circuitos flushados e testados quando aplicável conforme procedimento aprovado. O projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, a especificação técnica e o procedimento de flushing/teste definem os critérios de aceitação (grau de limpeza, pressão e duração). O critério "Circuitos flushados/testados quando aplicável" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a liberação para preservação e comissionamento.',
  texto_risco_consequencia = 'Circuitos internos não flushados ou com falha de estanqueidade permitem a permanência de contaminantes e o vazamento sob pressão, causando obstrução, dano a componentes internos, contaminação do fluido de processo e reprovação no comissionamento, com retrabalho e atraso. A permanência da condição mantém ativo o risco de contaminação e de vazamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar/repetir o flushing dos circuitos conforme procedimento aprovado, até atingir o grau de limpeza especificado, com inspeção dos filtros/telas de retenção; (ii) refazer o teste de estanqueidade na pressão e duração previstas, localizando e sanando pontos de vazamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de flushing e de teste de estanqueidade, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior ou Crítica quando a falha de preservação expuser o equipamento à corrosão, à entrada de umidade ou à deterioração de componentes internos até o comissionamento.',
  texto_fundamentacao_normativa = 'A preservação do equipamento entre a montagem e o comissionamento deve manter proteções físicas, dessecantes e a energização das resistências de aquecimento (space heaters) ativa, evitando condensação e corrosão interna durante o período de espera. O plano de preservação e o manual do fabricante definem periodicidade de inspeção, troca de dessecantes e condição de energização das resistências. O critério "Proteções, dessecantes e energização de resistências de aquecimento" integra o plano de inspeção e constitui requisito verificável de aceitação da fase de preservação, com registros datados de conferência.',
  texto_risco_consequencia = 'Equipamento sem preservação adequada fica exposto à condensação, corrosão de superfícies internas, enrolamentos e mancais e à deterioração de vedações, comprometendo o desempenho e a garantia antes mesmo da entrada em operação, com risco de substituição de componentes. A permanência da condição mantém ativa a exposição do equipamento à degradação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) restabelecer as proteções físicas (tampões, coberturas, lacres) e substituir dessecantes saturados, conferindo indicadores de umidade; (ii) verificar e reativar a energização das resistências de aquecimento, confirmando tensão e funcionamento, com atenção aos requisitos de segurança elétrica durante a intervenção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de preservação com data e responsável, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de relatórios ou certificados por TAG impedir a rastreabilidade e a liberação documental do equipamento para o comissionamento.',
  texto_fundamentacao_normativa = 'O data book de montagem consolida a rastreabilidade da atividade, reunindo por TAG os relatórios de nivelamento, alinhamento, torque, flushing, testes e os certificados de materiais e componentes, comprovando a conformidade da montagem executada. O plano da qualidade e o plano de inspeção e testes da obra, com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, definem os documentos exigíveis e a organização por TAG. O critério "Relatórios e certificados anexados por TAG" integra o plano de inspeção e constitui requisito verificável de aceitação documental, condicionando a liberação do equipamento para as fases subsequentes.',
  texto_risco_consequencia = 'Data book incompleto ou sem vínculo por TAG impede a comprovação da conformidade da montagem, dificulta a rastreabilidade em caso de falha e pode bloquear a liberação para comissionamento e a aceitação final da obra, gerando retrabalho de coleta documental e atraso. A permanência da condição mantém ativa a lacuna de rastreabilidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os documentos pendentes por TAG (relatórios de montagem e certificados de materiais/componentes), confrontando com o índice previsto no plano da qualidade; (ii) anexar e indexar os documentos faltantes no data book, corrigindo vínculos de TAG e assinaturas/aprovações; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o índice do data book atualizado, submetendo à reinspeção documental para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-05' and item_numero = 7;

-- ME-06 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o preparo insuficiente ocorrer em superfície de esquema anticorrosivo de alta durabilidade ou em ambiente agressivo, comprometendo a ancoragem de todo o sistema de pintura',
  texto_fundamentacao_normativa = 'O grau de limpeza da superfície define a ancoragem mecânica e a remoção de contaminantes (carepa de laminação, óxidos e ferrugem) que condicionam a aderência e a vida útil do revestimento anticorrosivo. A norma ISO 8501-1 estabelece os graus de preparo por jateamento abrasivo, entre eles o Sa 2½ citado no critério, e o esquema de pintura e a especificação do fabricante do revestimento, alinhados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, fixam o grau exigido para cada demão. O critério "Grau de limpeza (ex.: Sa 2½) inspecionado antes da demão" integra o plano de inspeção e constitui requisito verificável de aceitação anterior à aplicação da tinta.',
  texto_risco_consequencia = 'A aplicação de tinta sobre superfície com preparo inferior ao especificado resulta em ancoragem deficiente, permitindo delaminação precoce, empolamento e progressão de corrosão sob o filme, com necessidade de remoção e refazimento integral do esquema de pintura e antecipação da degradação do ativo. A permanência da condição mantém a superfície com preparo não conforme registrada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a aplicação e reavaliar o grau de limpeza do trecho por padrão visual comparativo (ISO 8501-1), confrontando com o grau Sa exigido no esquema de pintura; (ii) reexecutar o preparo de superfície (rejateamento ou limpeza mecânica conforme o caso) até atingir o grau especificado, com rugosidade/perfil de ancoragem dentro da faixa de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova inspeção de grau de limpeza antes de liberar a demão, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a demão tiver sido efetivamente aplicada fora dos limites ambientais (ex.: temperatura do substrato inferior a 3 °C acima do ponto de orvalho ou UR excessiva), comprometendo a cura e a aderência do filme',
  texto_fundamentacao_normativa = 'As condições ambientais no momento da aplicação — umidade relativa, temperatura do substrato e do ar e ponto de orvalho — governam a condensação superficial, a cura e a formação do filme; a regra consagrada de aplicar somente com a temperatura do substrato ao menos 3 °C acima do ponto de orvalho e UR dentro do limite evita condensação e falhas de aderência. Os limites aplicáveis constam da ficha técnica do fabricante do revestimento e do esquema de pintura vinculado ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "UR, temperatura e ponto de orvalho dentro dos limites" integra o plano de inspeção e constitui requisito verificável, com registro obrigatório antes e durante a aplicação.',
  texto_risco_consequencia = 'A aplicação em condições ambientais fora dos limites, ou sem o devido registro, favorece condensação interfacial, cura deficiente, embranquecimento e perda de aderência, comprometendo o desempenho anticorrosivo e exigindo remoção e reaplicação do revestimento. A ausência de registro ainda impede a rastreabilidade e a demonstração de conformidade da etapa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a aplicação e registrar imediatamente UR, temperaturas do ar e do substrato e ponto de orvalho, confrontando-os com os limites da ficha técnica e do esquema de pintura; (ii) somente retomar a aplicação quando as condições estiverem dentro dos limites, e avaliar a integridade das demãos aplicadas em condição irregular, removendo e reaplicando os trechos comprometidos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de condições ambientais assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a espessura medida ficar abaixo do mínimo especificado em área relevante ou em ambiente agressivo, reduzindo a barreira anticorrosiva projetada',
  texto_fundamentacao_normativa = 'A espessura de cada demão (úmida durante a aplicação e seca após cura) determina a barreira anticorrosiva e o desempenho do sistema; espessuras abaixo do mínimo reduzem a proteção e acima do máximo podem gerar tensões, fissuras e cura deficiente. Os valores de EPS úmida e seca por demão são definidos no esquema de pintura e na ficha técnica do fabricante, vinculados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "EPS úmida/seca conforme esquema de pintura" integra o plano de inspeção e constitui requisito verificável, medido por instrumento calibrado a cada demão.',
  texto_risco_consequencia = 'Espessura fora da faixa especificada compromete a proteção anticorrosiva: abaixo do mínimo, reduz a vida útil e antecipa a corrosão; acima do máximo, favorece fissuração, empolamento e cura interna incompleta, podendo exigir remoção e refazimento das demãos. A permanência da condição mantém o sistema de pintura com espessura não conforme registrada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir a espessura do trecho com medidor calibrado (EPS úmida durante a aplicação e EPS seca após cura), confrontando com os valores mínimo e máximo do esquema de pintura; (ii) corrigir a espessura conforme o desvio — aplicar demão adicional onde deficiente, ou remover e reaplicar onde excessiva/comprometida — restabelecendo a faixa especificada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e mapa de medições de espessura, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o ensaio de aderência, exigido em especificação, não for realizado ou resultar abaixo do valor mínimo, colocando em dúvida a integridade de todo o sistema aplicado',
  texto_fundamentacao_normativa = 'O ensaio de aderência por tração (pull-off), quando exigido, comprova quantitativamente a ancoragem do sistema de pintura ao substrato e entre demãos, sendo evidência direta da qualidade do preparo e da aplicação. O critério "Pull-off conforme especificação" remete ao valor mínimo de aderência, ao método e à frequência de ensaio fixados na especificação técnica e no esquema de pintura vinculados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O ensaio integra o plano de inspeção e constitui requisito verificável de aceitação nos casos em que a especificação o torna obrigatório.',
  texto_risco_consequencia = 'A ausência do ensaio quando exigido, ou resultado de aderência inferior ao mínimo, impede a comprovação da ancoragem e indica risco de delaminação e desprendimento do revestimento em serviço, com progressão de corrosão e necessidade de remoção e refazimento do sistema nas áreas afetadas. A não realização ainda compromete a rastreabilidade e a liberação da etapa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o ensaio de aderência por tração (pull-off) nos pontos e na frequência previstos na especificação, com equipamento calibrado, registrando valores e modo de ruptura; (ii) tratar as áreas reprovadas — remover o revestimento desaderido, reexecutar o preparo e reaplicar o esquema — e reensaiar até atingir o valor mínimo especificado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de ensaio de aderência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o dano à camada galvanizada não for retocado ou o retoque não atingir a espessura/produto normativos em componente estrutural ou exposto a meio agressivo',
  texto_fundamentacao_normativa = 'A camada de zinco confere proteção catódica e de barreira ao aço galvanizado; áreas danificadas por corte, solda, manuseio ou transporte perdem essa proteção e exigem retoque com produto e espessura equivalentes à galvanização original. Os requisitos de produto (ex.: tinta rica em zinco) e de espessura de retoque, bem como o método de reparo, são definidos pela especificação e pela norma de referência do revestimento, alinhados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Produto e espessura conforme norma" integra o plano de inspeção e constitui requisito verificável de aceitação das peças galvanizadas.',
  texto_risco_consequencia = 'Danos na galvanização sem retoque, ou retocados com produto/espessura inadequados, expõem o aço, criam pontos preferenciais de corrosão e comprometem a proteção catódica local, reduzindo a vida útil do componente e podendo exigir intervenção estrutural futura. A permanência da condição mantém as descontinuidades da camada de zinco registradas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear as áreas de galvanização danificada e preparar cada ponto por limpeza mecânica até o grau exigido; (ii) executar o retoque com o produto especificado (ex.: revestimento rico em zinco) e conferir a espessura de reparo conforme a norma e a especificação de referência; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e medição de espessura dos retoques, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou o erro de cor de segurança e TAG afetar identificação de tubulação/equipamento crítico ou sinalização de risco prevista na NR-26',
  texto_fundamentacao_normativa = 'A identificação final — aplicação de TAGs e das cores de segurança — assegura o reconhecimento inequívoco de equipamentos, tubulações e conteúdos e a sinalização de riscos na operação e manutenção. A NR-26 estabelece a sinalização de segurança e o emprego de cores para prevenção de acidentes, interface expressamente citada no critério; o padrão de cores, TAGs e legendas é complementado pela especificação do projeto e pelo esquema de identificação vinculados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "TAGs e cores de segurança (interface NR-26)" integra o plano de inspeção e constitui requisito verificável de conclusão da etapa.',
  texto_risco_consequencia = 'A ausência ou incorreção de TAGs e cores de segurança dificulta a identificação de equipamentos e conteúdos e enfraquece a sinalização de risco, aumentando a probabilidade de operação ou manutenção indevidas, de erro na resposta a emergências e de não conformidade com a NR-26. A permanência da condição mantém a identificação incompleta ou divergente registrada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a identificação aplicada com o esquema de cores, TAGs e legendas do projeto e com a sinalização de segurança prevista na NR-26; (ii) corrigir as divergências — aplicar as cores de segurança corretas e as TAGs/legendas faltantes ou trocadas nos equipamentos e tubulações; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e conferência final da identificação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ME-06' and item_numero = 6;

